    const [op, v] = Object.entries(c)[0]; const refs = indexProject(p);
    if (op === 'all' || op === 'any') return '(' + v.map(x => conditionText(x, p)).join(op === 'all' ? ' 且 ' : ' 或 ') + ')';
    if (op === 'not') return '未满足 ' + conditionText(v, p);
