    if (op === 'event_completed') return '达成 ' + (refs.events.get(v)?.title || v);
    if (op === 'variable') return (refs.variables.get(v.id)?.title || v.id) + ' ' + ({eq: '=', ne: '≠', gt: '>', gte: '≥', lt: '<', lte: '≤'}[v.op]) + ' ' + v.value;
